<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/public-discovery.php';
$viewer=current_user($pdo);if($viewer){header('Cache-Control: private, no-store');header('Vary: Cookie');}
$error='';$success='';$savedLoaded=null;
if($viewer&&isset($_GET['saved'])){$savedLoaded=search_saved_access($pdo,$viewer,(string)$_GET['saved']);if($savedLoaded){$_GET['q']=$savedLoaded['query_text'];$savedFilters=json_decode((string)$savedLoaded['filters_json'],true)?:[];foreach($savedFilters as $k=>$v)if(!isset($_GET[$k]))$_GET[$k]=$v;}}
$term=search_normalize_query((string)($_GET['q']??$_POST['q']??''));$filters=search_filters_from_input($_GET+$_POST);
$roomData=$viewer?live_rooms_for_user($pdo,$viewer):['teams'=>[],'projects'=>[]];$writeProjects=[];if($viewer){foreach($roomData['projects'] as $p)if(!empty($p['can_post']))$writeProjects[]=$p;}
if($_SERVER['REQUEST_METHOD']==='POST'&&$viewer){require_csrf();$action=(string)($_POST['action']??'');try{
    if($action==='save_search'){$scope=(string)($_POST['save_scope']??'private');$visibility='private';$scopeId=null;if(str_starts_with($scope,'team:')){$visibility='team';$scopeId=substr($scope,5);}elseif(str_starts_with($scope,'project:')){$visibility='project';$scopeId=substr($scope,8);}$saved=search_saved_create($pdo,$viewer,(string)($_POST['title']??''),$term,$filters,$visibility,$scopeId,!empty($_POST['alerts_enabled']));$success='Search saved.';$savedLoaded=search_saved_access($pdo,$viewer,$saved['public_id']);}
    elseif($action==='delete_saved'){if(!search_saved_delete($pdo,$viewer,(string)($_POST['saved_id']??'')))throw new RuntimeException('Only the saved-search owner can delete it.');$success='Saved search deleted.';}
    elseif($action==='toggle_alert'){if(!search_saved_alert_toggle($pdo,$viewer,(string)($_POST['saved_id']??''),!empty($_POST['enabled'])))throw new RuntimeException('Only the saved-search owner can change alerts.');$success='Saved-search alerts updated.';}
    elseif($action==='add_research'){$project=project_access($pdo,(int)$viewer['id'],(string)($_POST['project_id']??''));if(!$project||!project_can_write($project))throw new RuntimeException('Research write access required.');$kind=(string)($_POST['result_type']??'');$id=(string)($_POST['result_id']??'');if($kind==='annotation'){$a=annotation_access($pdo,$id,$viewer);if(!$a)throw new RuntimeException('Annotation not available.');$pdo->prepare('INSERT IGNORE INTO project_annotations(project_id,annotation_id,added_by_user_id) VALUES(?,?,?)')->execute([$project['id'],$a['id'],$viewer['id']]);}elseif($kind==='source'){$s=source_access($pdo,$id,$viewer);if(!$s)throw new RuntimeException('Source not available.');$pdo->prepare('INSERT IGNORE INTO project_sources(project_id,source_id,added_by_user_id) VALUES(?,?,?)')->execute([$project['id'],$s['id'],$viewer['id']]);}else throw new RuntimeException('This result type cannot be added directly.');$success='Added to Research.';}
}catch(Throwable $e){$error=$e->getMessage();}}
$results=search_unified($pdo,$term,$viewer,$filters);$total=(int)$results['meta']['total'];$savedSearches=$viewer?search_saved_list($pdo,$viewer):[];$recent=$viewer?search_recent($pdo,$viewer,8):[];
$typeLabels=['all'=>'All','sources'=>'Sources','annotations'=>'Annotations','people'=>'People','reports'=>'Reports','entities'=>'Entities','projects'=>'Projects','research'=>'Research objects'];
