<label>Sort<select name="sort"><option value="relevance" <?=$filters['sort']==='relevance'?'selected':''?>>Relevance</option><option value="newest" <?=$filters['sort']==='newest'?'selected':''?>>Newest</option><option value="discussed" <?=$filters['sort']==='discussed'?'selected':''?>>Most discussed</option></select></label>
