<label>Integrity<select name="integrity"><option value="">Any</option><?php foreach(['source_unchanged'=>'Source unchanged','source_updated'=>'Source updated','passage_changed'=>'Passage changed','passage_missing'=>'Passage missing','source_unavailable'=>'Source unavailable','source_restored'=>'Source restored'] as $k=>$v):?><option value="<?=h($k)?>" <?=$filters['integrity']===$k?'selected':''?>><?=h($v)?></option><?php endforeach?></select></label>
