<div class="searchTypeTabs"><?php foreach($typeLabels as $key=>$label):$qs=$_GET;$qs['type']=$key;?><a class="<?=$filters['type']===$key?'active':''?>" href="/search.php?<?=h(http_build_query($qs))?>"><?=h($label)?></a><?php endforeach?></div>
<div class="searchResultsGrid phase10Results">
<?php if($filters['type']==='all'||$filters['type']==='sources'):?><section><h2>Sources <span class="meta"><?=count($results['sources'])?></span></h2><?php foreach($results['sources'] as $s):?><article class="card sourceCard"><div class="meta"><?=h($s['domain'])?> · <?=h($s['status'])?> · <?=h((string)$s['annotation_count'])?> accessible annotations</div><h3><a href="/source.php?id=<?=h($s['public_id'])?>"><?=h($s['title']?:$s['canonical_url'])?></a></h3><?php if($viewer&&$writeProjects):?><form method="post" class="searchAddResearch"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add_research"><input type="hidden" name="q" value="<?=h($term)?>"><input type="hidden" name="result_type" value="source"><input type="hidden" name="result_id" value="<?=h($s['public_id'])?>"><select name="project_id"><?php foreach($writeProjects as $p):?><option value="<?=h($p['public_id'])?>"><?=h($p['title'])?></option><?php endforeach?></select><button class="button secondary">Add to Research</button></form><?php endif?></article><?php endforeach?><?php if(!$results['sources']):?><div class="card">No accessible sources found.</div><?php endif?></section><?php endif?>
<?php if($filters['type']==='all'||$filters['type']==='annotations'):?><section><h2>Annotations <span class="meta"><?=count($results['annotations'])?></span></h2><?php foreach($results['annotations'] as $a):?><article class="card"><div class="meta"><a href="/profile.php?u=<?=h($a['username'])?>"><?=h($a['display_name'])?></a> · <a href="/source.php?id=<?=h($a['source_public_id'])?>"><?=h($a['source_title']?:$a['domain'])?></a> · <span class="badge <?=in_array($a['integrity']['impact_type'],['passage_changed','passage_missing','source_unavailable'],true)?'warn':''?>"><?=h($a['integrity']['label'])?></span></div><?php if($a['text_commentary']):?><p><?=nl2br(h(public_discovery_meta_description($a['text_commentary'],520)))?></p><?php endif?><?php if($a['selected_text']):?><blockquote><?=h(mb_substr($a['selected_text'],0,500))?></blockquote><?php endif?><?php if($a['transcript_text']):?><details><summary>Transcript match</summary><p><?=nl2br(h(mb_substr($a['transcript_text'],0,900)))?></p></details><?php endif?><div class="inlineActions"><a href="/annotation.php?id=<?=h($a['public_id'])?>">Open annotation</a><?php if($viewer&&$writeProjects):?><form method="post" class="searchAddResearch"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add_research"><input type="hidden" name="q" value="<?=h($term)?>"><input type="hidden" name="result_type" value="annotation"><input type="hidden" name="result_id" value="<?=h($a['public_id'])?>"><select name="project_id"><?php foreach($writeProjects as $p):?><option value="<?=h($p['public_id'])?>"><?=h($p['title'])?></option><?php endforeach?></select><button class="button secondary">Add to Research</button></form><?php endif?></div></article><?php endforeach?><?php if(!$results['annotations']):?><div class="card">No accessible annotations found.</div><?php endif?></section><?php endif?>
