<?php if($filters['type']==='all'||$filters['type']==='entities'):?><section><h2>Entities & topics <span class="meta"><?=count($results['entities'])?></span></h2><?php foreach($results['entities'] as $e):?><a class="card sourceCard" href="<?=$e['scope']==='public'?'/entity.php?id='.h($e['public_id']):'/research-entity.php?id='.h($e['public_id'])?>"><div class="meta"><?=h($e['entity_type'])?> · <?=h($e['scope'])?> · <?=h((string)$e['mention_count'])?> mentions</div><h3><?=h($e['canonical_name'])?></h3><?php if($e['description']):?><p><?=h(public_discovery_meta_description($e['description'],240))?></p><?php endif?></a><?php endforeach?><?php if(!$results['entities']):?><div class="card">No entities found.</div><?php endif?></section><?php endif?>
<?php if($viewer&&($filters['type']==='all'||$filters['type']==='projects')):?><section><h2>Research projects <span class="meta"><?=count($results['projects'])?></span></h2><?php foreach($results['projects'] as $p):?><a class="card sourceCard" href="/research-project.php?id=<?=h($p['public_id'])?>"><div class="meta"><?=h($p['access_role'])?></div><h3><?=h($p['title'])?></h3><?php if($p['description']):?><p><?=h(public_discovery_meta_description($p['description'],240))?></p><?php endif?></a><?php endforeach?><?php if(!$results['projects']):?><div class="card">No accessible projects found.</div><?php endif?></section><?php endif?>
<?php if($viewer&&($filters['type']==='all'||$filters['type']==='research')):?><section><h2>Findings & claims <span class="meta"><?=count($results['research'])?></span></h2><?php foreach($results['research'] as $r):?><a class="card sourceCard" href="<?=$r['object_type']==='claim'?'/research-claim.php?id=':'/research-finding.php?id='?><?=h($r['public_id'])?>"><div class="meta"><?=h($r['project_title'])?> · <?=h($r['object_type'])?></div><h3><?=h($r['title'])?></h3><?php if($r['snippet']):?><p><?=h(public_discovery_meta_description($r['snippet'],280))?></p><?php endif?></a><?php endforeach?><?php if(!$results['research']):?><div class="card">No matching Research objects found.</div><?php endif?></section><?php endif?>
</div><?php endif?></section>
